performance-loop-protocol.harness_source:
import os,sys,json,time,random,hashlib,itertools,statistics as T,subprocess as S,shutil,copy
from pathlib import Path as P
import xml.etree.ElementTree as E
root=P.cwd(); work=root/'generated/performance-continuation'; out=root/'artifacts/aro2-performance-continuation'
os.environ['PATH']='/home/aron/.local/share/mise/installs/node/26.7.0/bin:'+os.environ['PATH'];os.environ['ARO2_NODE']='/home/aron/.local/share/mise/installs/node/26.7.0/bin/node'
manifest='tools/bot-evaluation/Cargo.toml';exe=root/'tools/bot-evaluation/target/release/ascencio-bot-evaluation'
def cmd(args):
 r=S.run(args,stdout=S.PIPE,stderr=S.PIPE,text=True)
 if r.returncode: raise RuntimeError(str(args)+'\n'+r.stdout+'\n'+r.stderr)
 return r

def save(tree,path):
 data=E.tostring(tree,encoding='utf-8',xml_declaration=True)
 with open(str(path)+'.tmp','wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
 os.replace(str(path)+'.tmp',path)

def permutation(d):
 observed=sum(d)
 return sum(sum(a*b for a,b in zip(d,signs))>=observed-1e-10 for signs in itertools.product([-1,1],repeat=len(d)))/2**len(d)

def experiment(node,phase,old,new,paths):
 trials=E.SubElement(node,'phase',name=phase);base=0 if phase=='screen' else 12
 orders=['baseline','candidate']*6;random.SystemRandom().shuffle(orders)
 means={a:[] for a in ['baseline','candidate']};values={a:[] for a in means}
 for i,first in enumerate(orders):
  for arm in [first, 'candidate' if first=='baseline' else 'baseline']:
   for p in paths:P(p).write_bytes((old if arm=='baseline' else new)[p])
   load_before=P('/proc/loadavg').read_text().strip()
   r=cmd([str(work/arm),'benchmark','--config',str(work/f'config-{base+i:02}.xml')]);directory=P(r.stdout.strip());summary=E.parse(directory/'summary.xml').getroot();perf=summary.find('performance')
   assert summary.findtext('counts/games_completed')=='4' and summary.findtext('counts/games_failed')=='0'
   samples=[float(g.findtext('duration_ms')) for g in perf.findall('game_samples/game')];assert len(samples)==4
   means[arm].append(T.mean(samples));values[arm]+=samples
   n=E.SubElement(trials,'observation',arm=arm,pair=str(i),fixture=f'orders-{base+i:02}.xml',run_id=directory.name,path=str(directory));n.append(perf);E.SubElement(n,'stderr').text=r.stderr;E.SubElement(n,'load_before').text=load_before;E.SubElement(n,'load_after').text=P('/proc/loadavg').read_text().strip()
   inv=E.SubElement(n,'evidence')
   for f in sorted(directory.rglob('*.xml')):E.SubElement(inv,'file',path=str(f.relative_to(directory)),sha256=hashlib.sha256(f.read_bytes()).hexdigest(),bytes=str(f.stat().st_size))
   # Workload counts are recorded, not used to discard slow games.
   for a in ['a','b']:
    rep=E.parse(directory/f'matches/match-000001/player-{a}.xml').getroot()
    for j,g in enumerate(rep.findall('games/game')):E.SubElement(n,'workload',actor=a,game=str(j+1),entries=str(len(g.findall('timeline/entry'))),turns=g.findtext('result/turns',''),evidence_sha256=g.findtext('result/evidence_sha256',''))
   save(node,out/f"iteration-{node.get('number')}.xml")
 d=[a-b for a,b in zip(means['baseline'],means['candidate'])];p=permutation(d)
 for a,v in values.items():E.SubElement(trials,'statistics',arm=a,n=str(len(v)),mean_ms=str(T.mean(v)),variance_ms2=str(T.variance(v)),minimum_ms=str(min(v)),maximum_ms=str(max(v)))
 improvement=100*T.mean(d)/T.mean(means['baseline']);passed=p<=.005 and improvement>0
 E.SubElement(trials,'test',name='exact paired one-sided sign-flip',p=str(p),improvement_percent=str(improvement),passed=str(passed).lower())
 E.SubElement(trials,'profile').text=json.dumps({k:T.mean(float(x.text) for o in trials.findall('observation') if o.get('arm')=='baseline' for x in o.findall('performance/game_samples/game/costs/'+k)) for k in ['engine_time_ms','host_setup_ms','projection_ms','ipc_ms','evidence_hash_ms','serialization_ms','schema_validation_ms','filesystem_ms']})
 save(node,out/f"iteration-{node.get('number')}.xml")
 print(node.get('number'),phase,'baseline',T.mean(values['baseline']),'candidate',T.mean(values['candidate']),'p',p,'gain%',improvement,flush=True)
 return passed
statefile=work/'state.xml'
state=E.parse(statefile).getroot() if statefile.exists() else E.Element('state',next='11',streak='10',cursor='0',retained='0')
catalog=json.loads((work/'catalog.json').read_text())
head=cmd(['git','rev-parse','HEAD']).stdout.strip()
if not (work/'baseline-head').exists() or (work/'baseline-head').read_text()!=head:
 cmd(['cargo','build','--release','--manifest-path',manifest]);shutil.copy2(exe,work/'baseline');(work/'baseline-head').write_text(head)
for index in range(int(state.get('cursor')),len(catalog)):
 if int(state.get('streak'))>=100:break
 c=catalog[index];number=state.get('next');paths=list(c['edits']);old={p:P(p).read_bytes() for p in paths};new={}
 for p,replacements in c['edits'].items():
  text=old[p].decode()
  for a,b in replacements:
   if a not in text:raise RuntimeError('Patch no longer applies: '+c['name']+' '+p+' '+a[:100])
   text=text.replace(a,b)
  new[p]=text.encode()
 if old==new:raise RuntimeError('No-op candidate '+c['name'])
 node=E.Element('optimization-iteration',number=number,name=c['name'],base_commit=head,prior_streak=state.get('streak'));E.SubElement(node,'rationale').text=c['rationale'];E.SubElement(node,'phase_basis').text='Historical and preceding per-game profiles show IPC/serialization/hash/validation allocations on measured path; candidate targets '+c['area']
 print('START',number,c['name'],'streak',state.get('streak'),flush=True)
 keep=False
 try:
  for p,b in new.items():P(p).write_bytes(b)
  E.SubElement(node,'patch').text=cmd(['git','diff','--',*paths]).stdout
  build=cmd(['cargo','build','--release','--manifest-path',manifest]);E.SubElement(node,'build').text=build.stderr
  shutil.copy2(exe,work/'candidate');E.SubElement(node,'binary',arm='baseline',sha256=hashlib.sha256((work/'baseline').read_bytes()).hexdigest());E.SubElement(node,'binary',arm='candidate',sha256=hashlib.sha256((work/'candidate').read_bytes()).hexdigest())
  context=cmd(['npm','run','test:context']);E.SubElement(node,'test_selection_context').text=context.stdout+context.stderr
  test=cmd(['npm','test','--','--tests','tests/bot-evaluation-tooling.test.ts']);E.SubElement(node,'regression_validation').text=test.stdout+test.stderr
  if any(p.endswith('.ts') for p in paths):
   test=cmd(['npm','test','--','--tests','tests/unit/bot-evaluation-events.test.ts','tests/unit/bot-contract.test.ts','tests/unit/card-visibility.test.ts','tests/unit/prompt-registry-visibility.test.ts']);E.SubElement(node,'visibility_validation').text=test.stdout+test.stderr
  if experiment(node,'screen',old,new,paths):keep=experiment(node,'confirmation',old,new,paths)
  if keep:
   for p,b in new.items():P(p).write_bytes(b)
   os.environ['ARO2_ACCEPTANCE_SNAPSHOT']=str(root/'generated/performance-loop/verified')
   test=cmd(['npm','test','--','--tests','tests/bot-evaluation-acceptance.test.ts','tests/bot-evaluation-tooling.test.ts','tests/unit/bot-contract.test.ts','tests/unit/bot-evaluation-events.test.ts','tests/unit/card-visibility.test.ts','tests/unit/prompt-registry-visibility.test.ts']);E.SubElement(node,'retention_validation').text=test.stdout+test.stderr
  state.set('streak','0' if keep else str(int(state.get('streak'))+1));state.set('next',str(int(number)+1));state.set('cursor',str(index+1))
  if keep:state.set('retained',str(int(state.get('retained'))+1))
  E.SubElement(node,'decision',retain=str(keep).lower(),streak=state.get('streak'))
  save(node,out/f'iteration-{number}.xml');save(state,statefile)
 except Exception as e:
  keep=False;E.SubElement(node,'incomplete_error').text=str(e);save(node,out/f'iteration-{number}-incomplete.xml');raise
 finally:
  for p,b in (new if keep else old).items():P(p).write_bytes(b)
 if keep:
  print('RETAIN_PENDING_COMMIT_AND_PUSH',number,c['name'],flush=True);sys.exit(10)
print('STOP',E.tostring(state,encoding='unicode'),flush=True)
